WITH sales_by_store_year AS ( SELECT s.s_store_sk, s.s_store_name, d.d_year, SUM(ss.ss_net_profit) AS total_profit, SUM(ss.ss_net_paid) AS total_paid, SUM(ss.ss_ext_discount_amt) AS total_discount, AVG(cd.cd_purchase_estimate) AS avg_purchase_estimate, MAX(CASE WHEN s.s_closed_date_sk IS NOT NULL THEN 1 ELSE 0 END) AS is_closed FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk GROUP BY s.s_store_sk, s.s_store_name, d.d_year ) SELECT s_store_sk, s_store_name, d_year, total_profit, total_paid, total_discount, avg_purchase_estimate, CASE WHEN is_closed = 1 THEN 'Closed' ELSE 'Open' END AS store_status, DENSE_RANK() OVER (PARTITION BY d_year ORDER BY total_profit DESC) AS profit_rank_year, RANK() OVER (PARTITION BY d_year ORDER BY total_profit DESC) AS profit_rank_year_alt FROM sales_by_store_year WHERE total_profit > 0 ORDER BY d_year DESC, profit_rank_year
